{
  "schema": 1,
  "version": 1,
  "id": "carousel",
  "name": "Carousel",
  "description": "A cover-focused home screen with a centered book, side previews, and a thicker outline while browsing covers.",
  "inherits": "lyra",
  "requires": {
    "crosspoint": {
      "schema": 1,
      "modules": [
        "cover-strip"
      ]
    }
  },
  "metrics": {
    "homeCoverHeight": 300,
    "homeCoverTileHeight": 340,
    "homeRecentBooksCount": 3,
    "homeMenuTopOffset": 8,
    "menuRowHeight": 56,
    "menuSpacing": 4
  },
  "components": {
    "homeRecents": {
      "type": "cover-strip",
      "maxBooks": 3,
      "wrap": true,
      "selectionLineWidth": 3,
      "inactiveSelectionLineWidth": 1,
      "selectionCornerRadius": 6,
      "slots": [
        {
          "book": "previous",
          "x": "padding",
          "y": "center",
          "height": 225,
          "widthPercent": 62
        },
        {
          "book": "selected",
          "x": "center",
          "y": "top",
          "height": 300,
          "widthPercent": 62,
          "yOffset": 8,
          "selected": true,
          "title": {
            "enabled": true,
            "font": "large",
            "style": "bold",
            "maxLines": 2,
            "offsetY": 12
          }
        },
        {
          "book": "next",
          "x": "right-padding",
          "y": "center",
          "height": 225,
          "widthPercent": 62
        }
      ]
    },
    "homeMenu": {
      "font": "large",
      "style": "regular",
      "centeredText": false,
      "showIcons": true,
      "drawPanel": false,
      "selectionStyle": "fill",
      "selectionCornerRadius": 6,
      "selectionInset": 20
    },
    "list": {
      "font": "medium",
      "style": "regular",
      "showIcons": true,
      "textGap": 8,
      "selectionCornerRadius": 6,
      "selectionFill": true,
      "selectionOutline": false,
      "selectedTextInverted": false,
      "selectionInsetX": 0,
      "selectionInsetY": 0,
      "titleOffsetY": 7,
      "subtitleOffsetY": 30,
      "valueOffsetY": 6,
      "subtitleValueOffsetY": 16,
      "iconOffsetY": 0
    },
    "buttonHints": {
      "font": "small",
      "style": "regular",
      "buttonWidth": 80,
      "smallButtonHeight": 15,
      "cornerRadius": 6,
      "fill": true,
      "outline": true,
      "drawEmpty": true,
      "textOffsetY": 7
    }
  },
  "assets": {
    "freeInkIcons": {
      "book": "book-open",
      "book24": "book-open",
      "bookmark": "bookmark",
      "cover": "book-open",
      "file24": "file",
      "folder": "folder",
      "folder24": "folder",
      "hotspot": "router",
      "image24": "image",
      "library": "library",
      "recent": "clock-3",
      "settings": "sliders-horizontal",
      "text24": "file-text",
      "transfer": "download",
      "wifi": "wifi"
    },
    "icons": {
      "book": "icons/book.bmp",
      "book24": "icons/book24.bmp",
      "bookmark": "icons/bookmark.bmp",
      "cover": "icons/cover.bmp",
      "file24": "icons/file24.bmp",
      "folder": "icons/folder.bmp",
      "folder24": "icons/folder24.bmp",
      "hotspot": "icons/hotspot.bmp",
      "image24": "icons/image24.bmp",
      "library": "icons/library.bmp",
      "recent": "icons/recent.bmp",
      "settings": "icons/settings.bmp",
      "text24": "icons/text24.bmp",
      "transfer": "icons/transfer.bmp",
      "wifi": "icons/wifi.bmp"
    }
  },
  "devices": {
    "x3": {
      "constraints": {
        "screenWidth": 480,
        "screenHeight": 800,
        "frontButtons": 4,
        "sideButtons": "up-down"
      },
      "components": {
        "homeRecents": {
          "slots": [
            {
              "book": "previous",
              "x": "padding",
              "y": "center",
              "height": 210,
              "widthPercent": 62
            },
            {
              "book": "selected",
              "x": "center",
              "y": "top",
              "height": 280,
              "widthPercent": 62,
              "yOffset": 8,
              "selected": true,
              "title": {
                "enabled": true,
                "font": "large",
                "style": "bold",
                "maxLines": 2,
                "offsetY": 12
              }
            },
            {
              "book": "next",
              "x": "right-padding",
              "y": "center",
              "height": 210,
              "widthPercent": 62
            }
          ]
        }
      }
    },
    "x4": {
      "constraints": {
        "screenWidth": 480,
        "screenHeight": 800,
        "frontButtons": 0,
        "sideButtons": "up-down"
      }
    }
  },
  "extensions": {
    "crossink": {
      "readingStatsFooter": true
    }
  }
}

{
  "schema": 1,
  "version": 1,
  "id": "super-minimal",
  "name": "Super Minimal",
  "description": "A quiet text-only theme with no cover area, centered home options, underline selection, and icon-only hints.",
  "inherits": "lyra",
  "metrics": {
    "headerHeight": 48,
    "tabBarHeight": 36,
    "homeTopPadding": 48,
    "homeCoverHeight": 0,
    "homeCoverTileHeight": 0,
    "homeRecentBooksCount": 1,
    "homeContinueReadingInMenu": true,
    "homeShowContinueReadingHeader": true,
    "homeMenuTopOffset": 0,
    "menuRowHeight": 42,
    "menuSpacing": 6
  },
  "components": {
    "homeRecents": {
      "type": "none"
    },
    "homeMenu": {
      "font": "medium",
      "style": "regular",
      "centeredText": true,
      "centerVertically": true,
      "showIcons": false,
      "drawPanel": false,
      "panelWidth": 360,
      "selectionStyle": "underline",
      "selectionCornerRadius": 6,
      "selectionInset": 18
    },
    "list": {
      "font": "medium",
      "style": "regular",
      "showIcons": false,
      "textGap": 0,
      "selectionStyle": "underline",
      "selectionCornerRadius": 0,
      "selectionFill": false,
      "selectionOutline": false,
      "selectedTextInverted": false,
      "selectionInsetX": 0,
      "selectionInsetY": 0,
      "titleOffsetY": 7,
      "subtitleOffsetY": 30,
      "valueOffsetY": 6,
      "subtitleValueOffsetY": 16,
      "iconOffsetY": 0
    },
    "header": {
      "font": "medium",
      "style": "regular",
      "centeredTitle": true,
      "showDivider": false,
      "titleOffsetY": 0
    },
    "tabBar": {
      "font": "medium",
      "style": "regular",
      "equalWidth": true,
      "selectionStyle": "underline",
      "selectedTextInverted": false,
      "drawDivider": false,
      "horizontalInset": 2
    },
    "buttonHints": {
      "font": "small",
      "style": "regular",
      "buttonWidth": 80,
      "smallButtonHeight": 15,
      "cornerRadius": 6,
      "fill": false,
      "outline": false,
      "drawEmpty": false,
      "shapeSize": 18,
      "textOffsetY": 7,
      "layout": "shapes"
    }
  },
  "screens": {
    "home": {
      "layout": {
        "type": "rows",
        "padding": {
          "x": 60,
          "top": 120,
          "bottom": 120
        },
        "gap": 0,
        "children": [
          {
            "type": "box",
            "outline": false,
            "fill": false
          },
          {
            "type": "menu-grid",
            "h": 220,
            "columns": 1,
            "gap": 8,
            "font": "medium",
            "radius": 0,
            "outline": false,
            "fill": false
          },
          {
            "type": "box",
            "outline": false,
            "fill": false
          }
        ]
      }
    }
  },
  "devices": {
    "x3": {
      "constraints": {
        "screenWidth": 480,
        "screenHeight": 800,
        "frontButtons": 4,
        "sideButtons": "up-down"
      }
    },
    "x4": {
      "constraints": {
        "screenWidth": 480,
        "screenHeight": 800,
        "frontButtons": 0,
        "sideButtons": "up-down"
      }
    }
  },
  "extensions": {
    "crossink": {
      "reference": "src/components/themes/minimal"
    }
  }
}
